134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Override
136	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
137	        List<String> missingFields = new ArrayList<>();
138	        if (isBlank(ownerFieldsDto.getFirstName())) {
139	            missingFields.add("firstName");
140	        }
141	        if (isBlank(ownerFieldsDto.getLastName())) {
142	            missingFields.add("lastName");
143	        }
144	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
145	        if (isBlank(normalizedAddress)) {
146	            missingFields.add("address");
147	        }
148	        if (isBlank(ownerFieldsDto.getCity())) {
149	            missingFields.add("city");
150	        }
151	        if (isBlank(ownerFieldsDto.getTelephone())) {
152	            missingFields.add("telephone");
153	        }
154	        if (!missingFields.isEmpty()) {
155	            throw new MissingOwnerFieldsException(missingFields);
156	        }
157	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
158	        LocalDate suppliedRegistrationDate = ownerFieldsDto.getRegistrationDate();
159	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
160	            throw new FutureRegistrationDateException(
161	                "registrationDate must not be later than the server date");
162	        }
163	        LocalDate registrationDate = toBusinessDay(
164	            suppliedRegistrationDate != null
165	                ? suppliedRegistrationDate
166	                : LocalDate.now());
167	        long registeredOnDay = this.clinicService.findAllOwners().stream()
168	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
169	            .count();
170	        if (registeredOnDay >= 100) {
171	            throw new DailyRegistrationLimitException(
172	                "100 or more owners have already been registered today");
173	        }
174	        boolean bulkSignupWarning = registeredOnDay > 80;
175	        String city = ownerFieldsDto.getCity();
176	        long ownersInCity = this.clinicService.findAllOwners().stream()
177	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
178	            .count();
179	        if (ownersInCity >= 50) {
180	            throw new CityAtCapacityException(
181	                "the owner's city already contains 50 or more owners");
182	        }
183	        ownerFieldsDto.setAddress(normalizedAddress);
184	        String telephone = toE164(ownerFieldsDto.getTelephone());
185	        ownerFieldsDto.setTelephone(telephone);
186	        String email = normalizeEmail(ownerFieldsDto.getEmail());
187	        ownerFieldsDto.setEmail(email);
188	        String lastName = normalizeHousehold(ownerFieldsDto.getLastName());
189	        String postcode = ownerFieldsDto.getPostcode();
190	        // Deterministic household id: owners with the same normalized last name and postcode
191	        // share it automatically, regardless of creation order. It is no longer created by the
192	        // 'sharesHousehold' flag; that flag now only bypasses the duplicate block below.
193	        String householdId = householdId(lastName, postcode);
194	        // The household is keyed on (last name, postcode), so its existing members are the
195	        // existing owners with the same computed household id. Both the duplicate block and the
196	        // household size below key off this value.
197	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
198	            .filter(existing -> householdId.equals(
199	                householdId(normalizeHousehold(existing.getLastName()), existing.getPostcode())))
200	            .toList();
201	        // Household duplicate block: a second owner in an existing household is rejected as a
202	        // household duplicate (409) unless the request opts in via 'sharesHousehold'. Opting in
203	        // only bypasses this block; the owner is then created as a declared household member.
204	        if (!householdMembers.isEmpty()
205	            && !Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
206	            throw new DuplicateHouseholdException(
207	                "an owner with the same last name and postcode already exists");
208	        }
209	        // Single, consolidated duplicate check: reject only when the new owner's whole
210	        // derived identity key (telephone|email|householdId) equals an existing owner's.
211	        String identityKey = IdentityKeyDeriver.identityKey(telephone, email, householdId);
212	        boolean identityInUse = this.clinicService.findAllOwners().stream()
213	            .anyMatch(existing -> identityKey.equals(IdentityKeyDeriver.identityKey(
214	                existing.getTelephone(), existing.getEmail(),
215	                householdId(normalizeHousehold(existing.getLastName()), existing.getPostcode()))));
216	        if (identityInUse) {
217	            throw new DuplicateIdentityException(
218	                "an owner with the same identity key already exists");
219	        }
220	        HttpHeaders headers = new HttpHeaders();
221	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
222	        owner.setRegistrationDate(registrationDate);
223	        owner.setCustomerCode(deduplicateCustomerCode(
224	            customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName())));
225	        owner.setHouseholdId(householdId);
226	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
227	        owner.setBulkSignupWarning(bulkSignupWarning);
228	        // Household size after this create: existing members plus the owner being created.
229	        owner.setHouseholdSize(householdMembers.size() + 1);
230	        // A declared household member is not a suspected duplicate, and no other create path
231	        // reaches here for a same-household owner, so a created owner is never flagged.
232	        owner.setPossibleDuplicate(false);
233	        owner.setPossibleDuplicateOf(null);
234	        this.clinicService.saveOwner(owner);
235	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
236	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} "
237	            + "membershipNumber={}",
238	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
239	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
240	        headers.setLocation(UriComponentsBuilder.newInstance()
241	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
242	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
243	    }
