343	    /**
344	     * Rolls a registration date forward to the next business day: when it falls on a Saturday or
345	     * Sunday it is advanced to the following Monday; a weekday is returned unchanged. This is applied
346	     * to the effective registration date (whether supplied in the request or defaulted to the server
347	     * date), so every value derived from the registration date sees the adjusted business day.
348	     */
349	    private static LocalDate toBusinessDay(LocalDate date) {
350	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
351	            date = date.plusDays(1);
352	        }
353	        return date;
354	    }
