356	    /**
357	     * Normalizes a last name for household-duplicate comparison: leading and trailing whitespace is
358	     * trimmed, every internal run of whitespace is collapsed to a single space, and the result is
359	     * lower-cased so that last names are compared case-insensitively.
360	     */
361	    private static String normalizeHousehold(String value) {
362	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
363	    }
364	
365	    /** Common street-type abbreviations expanded to their canonical full form during normalization. */
366	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
367	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
368	
369	    /**
370	     * Normalizes an address to its canonical stored form: leading and trailing whitespace is
371	     * trimmed, every internal run of whitespace is collapsed to a single space, the result is
372	     * upper-cased, and common street-type abbreviations are expanded token-by-token
373	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
374	     * whitespace-only value normalizes to the empty string. This form is both stored/returned and
375	     * used for every address comparison (household-duplicate detection and the shared household id).
376	     */
377	    private static String normalizeAddress(String value) {
378	        if (value == null) {
379	            return "";
380	        }
381	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
382	        if (collapsed.isEmpty()) {
383	            return "";
384	        }
385	        String[] tokens = collapsed.split(" ");
386	        StringBuilder sb = new StringBuilder();
387	        for (int i = 0; i < tokens.length; i++) {
388	            if (i > 0) {
389	                sb.append(' ');
390	            }
391	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
392	        }
393	        return sb.toString();
394	    }
395	
396	    /**
397	     * Derives the stable {@code householdId} shared by all owners in a household: the first 12
398	     * hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. It is a pure,
399	     * deterministic function of the normalized last name and postcode, so every owner that shares
400	     * those values maps to the same identifier regardless of creation order. A {@code null}
401	     * postcode contributes the empty string.
402	     */
403	    private static String householdId(String normalizedLastName, String postcode) {
404	        String key = normalizedLastName + "|" + (postcode == null ? "" : postcode);
405	        return sha256Hex12(key);
406	    }
407	
408	    /** The first 12 lower-case hex characters (6 bytes) of the SHA-256 digest of {@code s}. */
409	    private static String sha256Hex12(String s) {
410	        try {
411	            byte[] digest = MessageDigest.getInstance("SHA-256")
412	                .digest(s.getBytes(StandardCharsets.UTF_8));
413	            StringBuilder sb = new StringBuilder(12);
414	            for (int i = 0; i < 6; i++) {
415	                sb.append(String.format("%02x", digest[i]));
416	            }
417	            return sb.toString();
418	        }
419	        catch (NoSuchAlgorithmException e) {
420	            throw new IllegalStateException("SHA-256 not available", e);
421	        }
422	    }
423	
424	    /**
425	     * Builds the {@code customerCode} assigned to a new owner, formatted
426	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the region code derived from the owner's postcode
427	     * ({@code NSW}/{@code VIC}/{@code QLD}, or {@code UNKNOWN}), and {@code HASH8} is the first 8
428	     * upper-case hex characters of SHA-256 over the owner's normalized E.164 telephone concatenated
429	     * with the last name (e.g. {@code 'NSW-1A2B3C4D'}). No sequence number is used, so the code is a
430	     * pure function of the owner's own identity fields.
431	     */
432	    private static String customerCode(String postcode, String telephone, String lastName) {
433	        String region = LocalityDeriver.region(postcode);
434	        String hash8 = sha256Hex8((telephone == null ? "" : telephone)
435	            + (lastName == null ? "" : lastName));
436	        return region + "-" + hash8;
437	    }
438	
439	    /**
440	     * De-duplicates a computed {@code customerCode} against the codes already assigned to existing
441	     * owners. If {@code base} is not currently in use it is returned unchanged; otherwise
442	     * {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that yields a code no
443	     * existing owner holds (e.g. a second collision on {@code 'NSW-1A2B3C4D'} becomes
444	     * {@code 'NSW-1A2B3C4D-2'}, a third {@code 'NSW-1A2B3C4D-3'}, and so on).
445	     */
446	    private String deduplicateCustomerCode(String base) {
447	        Set<String> existing = this.clinicService.findAllOwners().stream()
448	            .map(Owner::getCustomerCode)
449	            .filter(code -> code != null)
450	            .collect(Collectors.toSet());
451	        if (!existing.contains(base)) {
452	            return base;
453	        }
454	        int n = 2;
455	        while (existing.contains(base + "-" + n)) {
456	            n++;
457	        }
458	        return base + "-" + n;
459	    }
460	
461	    /** The first 8 upper-case hex characters (4 bytes) of the SHA-256 digest of {@code s}. */
462	    private static String sha256Hex8(String s) {
463	        try {
464	            byte[] digest = MessageDigest.getInstance("SHA-256")
465	                .digest(s.getBytes(StandardCharsets.UTF_8));
466	            StringBuilder sb = new StringBuilder(8);
467	            for (int i = 0; i < 4; i++) {
468	                sb.append(String.format("%02X", digest[i]));
469	            }
470	            return sb.toString();
471	        }
472	        catch (NoSuchAlgorithmException e) {
473	            throw new IllegalStateException("SHA-256 not available", e);
474	        }
475	    }
476	
477	    /**
478	     * Counts the existing owners that share the given first name and last name, compared
479	     * case-insensitively. This is evaluated over the owners that already exist (i.e. before the
480	     * owner currently being created is saved), so it reflects how many namesakes preceded the
481	     * new owner.
482	     */
483	    private int countNamesakes(String firstName, String lastName) {
484	        return (int) this.clinicService.findAllOwners().stream()
485	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
486	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
487	            .count();
488	    }
