490	    /**
491	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. A
492	     * leading {@code '+'} and its country code are kept as-is; otherwise the number is treated as a
493	     * national one, a single leading {@code '0'} is dropped, and the default country code
494	     * {@code '+61'} is prepended. The result must have 8 to 15 digits after the {@code '+'}, and its
495	     * national number must have the length required by its country code ({@code '+61'} requires 9
496	     * national digits, {@code '+1'} requires 10); otherwise an {@link InvalidTelephoneException} is
497	     * raised (reported to the client as 400).
498	     */
499	    private static String toE164(String telephone) {
500	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()-]", "");
501	        String digits;
502	        if (cleaned.startsWith("+")) {
503	            digits = cleaned.substring(1);
504	        } else {
505	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
506	            digits = "61" + national;
507	        }
508	        if (!digits.matches("[0-9]{8,15}")) {
509	            throw new InvalidTelephoneException(
510	                "telephone must form a valid E.164 number with 8 to 15 digits");
511	        }
512	        validateNationalLength(digits);
513	        return "+" + digits;
514	    }
515	
516	    /** National-number length required for each supported country code (digits after the code). */
517	    private static final Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY_CODE = Map.of(
518	        "61", 9, "1", 10);
519	
520	    /**
521	     * Validates the national-number length of an E.164 number (digits after the {@code '+'}) against
522	     * its country code. {@code '+61'} requires 9 national digits and {@code '+1'} requires 10; a
523	     * mismatch raises an {@link InvalidTelephoneException} (reported to the client as 400). Country
524	     * codes without a configured requirement are left to the general 8-to-15-digit rule.
525	     */
526	    private static void validateNationalLength(String digits) {
527	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_COUNTRY_CODE.entrySet()) {
528	            String code = entry.getKey();
529	            if (digits.startsWith(code)) {
530	                int nationalLength = digits.length() - code.length();
531	                if (nationalLength != entry.getValue()) {
532	                    throw new InvalidTelephoneException(
533	                        "telephone national number must have " + entry.getValue()
534	                            + " digits for country code +" + code);
535	                }
536	                return;
537	            }
538	        }
539	    }
540	
541	    /**
542	     * Inclusive 4-digit postcode range fixed for each region: NSW 2000-2099, VIC 3000-3099,
543	     * QLD 4000-4099. A region absent from this table (i.e. a city with no known region) accepts
544	     * any 4-digit postcode.
545	     */
546	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
547	        "NSW", new int[] {2000, 2099},
548	        "VIC", new int[] {3000, 3099},
549	        "QLD", new int[] {4000, 4099});
550	
551	    /**
552	     * Validates an owner's optional {@code postcode}. When absent (or blank) it is left unvalidated
553	     * and the owner is accepted, keeping the request contract backward-compatible. When present it
554	     * must be a 4-digit value; and when the owner's city maps to a known region it must fall within
555	     * that region's fixed inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with
556	     * no known region accepts any 4-digit postcode. A violation raises an
557	     * {@link InvalidPostcodeException} (reported to the client as 400).
558	     */
559	    private static void validatePostcode(String city, String postcode) {
560	        if (isBlank(postcode)) {
561	            return;
562	        }
563	        if (!postcode.matches("[0-9]{4}")) {
564	            throw new InvalidPostcodeException("postcode must be a 4-digit value");
565	        }
566	        int[] range = REGION_POSTCODE_RANGE.get(LocalityDeriver.localityForCity(city));
567	        if (range == null) {
568	            return;
569	        }
570	        int value = Integer.parseInt(postcode);
571	        if (value < range[0] || value > range[1]) {
572	            throw new InvalidPostcodeException(
573	                "postcode is out of range for the owner's city region");
574	        }
575	    }
576	
577	    /**
578	     * Disposable email domains that are rejected outright: an owner whose email domain is one of
579	     * these is refused with a 400. Compared case-insensitively (the email is lower-cased before the
580	     * check).
581	     */
582	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
583	        "mailinator.com", "tempmail.com", "guerrillamail.com");
584	
585	    /**
586	     * Email is optional: an absent (or blank) value is left as {@code null}. When a value is
587	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
588	     * is raised (reported to the client as 400). Its domain must not be on the disposable-domain
589	     * blocklist ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}), otherwise
590	     * an {@link InvalidEmailException} is likewise raised (400). A valid value is returned lower-cased
591	     * so it is stored and returned in canonical form.
592	     */
593	    private static String normalizeEmail(String email) {
594	        if (isBlank(email)) {
595	            return null;
596	        }
597	        String trimmed = email.trim();
598	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
599	            throw new InvalidEmailException("email must be a syntactically valid address");
600	        }
601	        String normalized = trimmed.toLowerCase(Locale.ROOT);
602	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
603	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
604	            throw new InvalidEmailException("email domain is on the disposable-domain blocklist");
605	        }
606	        return normalized;
607	    }
608	}
